def _get_fenced_marker(code: str) -> str:
    markers = fenced_re.findall(code)
    if not markers:
        return '```'

    backtick_markers = [m for m in markers if m.startswith('`')]
    tilde_markers = [m for m in markers if m.startswith('~')]

    max_backticks = max((len(m) for m in backtick_markers), default=0)
    max_tildes = max((len(m) for m in tilde_markers), default=0)

    if max_backticks == 0:
        return '```'

    if max_tildes == 0:
        return '`' * (max_backticks + 1)

    return '`' * (max_backticks + 1)
